// Get the USGS earthquake data from the previous node
const usgsData = $input.all();

// Extract features array from the response
const features = usgsData[0].json.features || [];

// Map each earthquake to normalized format
const normalizedData = features.map(earthquake => {
  const props = earthquake.properties;
  const coords = earthquake.geometry.coordinates;

  return {
    json: {
      id: earthquake.id,
      type: 'earthquake',
      magnitude: props.mag,
      location: {
        longitude: coords[0],
        latitude: coords[1],
        depth: coords[2]
      },
      place: props.place,
      time: props.time,
      url: props.url
    }
  };
});

return normalizedData;

// Parse XML from GDACS API and normalize disaster data
const inputData = $input.all();
const normalizedItems = [];

for (const item of inputData) {
  // Get the XML response from the HTTP request
  const xmlData = item.json;

  // GDACS RSS feed typically has items in the 'item' array
  // Adjust based on actual XML structure
  let disasters = [];

  if (xmlData.rss && xmlData.rss.channel && xmlData.rss.channel.item) {
    disasters = Array.isArray(xmlData.rss.channel.item) 
      ? xmlData.rss.channel.item 
      : [xmlData.rss.channel.item];
  } else if (xmlData.item) {
    disasters = Array.isArray(xmlData.item) ? xmlData.item : [xmlData.item];
  }

  // Map each disaster to normalized format
  for (const disaster of disasters) {
    // Extract coordinates from georss:point or geo:lat/geo:long
    let coordinates = null;
    if (disaster['georss:point']) {
      const coords = disaster['georss:point'].split(' ');
      coordinates = {
        latitude: parseFloat(coords[0]),
        longitude: parseFloat(coords[1])
      };
    } else if (disaster['geo:lat'] && disaster['geo:long']) {
      coordinates = {
        latitude: parseFloat(disaster['geo:lat']),
        longitude: parseFloat(disaster['geo:long'])
      };
    }

    // Extract disaster type from category or title
    let disasterType = 'unknown';
    if (disaster.category) {
      disasterType = disaster.category.toLowerCase();
    } else if (disaster.title) {
      const title = disaster.title.toLowerCase();
      if (title.includes('flood')) disasterType = 'flood';
      else if (title.includes('earthquake')) disasterType = 'earthquake';
      else if (title.includes('cyclone') || title.includes('hurricane') || title.includes('typhoon')) disasterType = 'cyclone';
      else if (title.includes('volcano')) disasterType = 'volcano';
      else if (title.includes('drought')) disasterType = 'drought';
      else if (title.includes('wildfire') || title.includes('fire')) disasterType = 'wildfire';
    }

    // Extract severity from gdacs:severity or other fields
    let severity = 'unknown';
    if (disaster['gdacs:severity']) {
      severity = disaster['gdacs:severity'];
    } else if (disaster['gdacs:alertlevel']) {
      severity = disaster['gdacs:alertlevel'];
    }

    normalizedItems.push({
      json: {
        id: disaster.guid || disaster.link || `gdacs-${Date.now()}-${Math.random()}`,
        type: disasterType,
        severity: severity,
        location: coordinates,
        title: disaster.title || 'Unknown Disaster',
        description: disaster.description || disaster.summary || '',
        link: disaster.link || '',
        source: 'GDACS',
        timestamp: disaster.pubDate || disaster['dc:date'] || new Date().toISOString(),
        rawData: disaster
      }
    });
  }
}

return normalizedItems;

// Normalize OpenAQ v3 air quality data
const inputData = $input.all();
const normalizedData = [];

for (const item of inputData) {
  const results = item.json.results || [];

  for (const location of results) {
    // OpenAQ v3 API structure
    const locationId = location.id || null;
    const locationName = location.name || null;
    const locality = location.locality || null;
    const country = location.country?.name || null;
    const latitude = location.coordinates?.latitude || null;
    const longitude = location.coordinates?.longitude || null;

    // Get latest measurements array
    const latestMeasurements = location.latest || [];

    // Create an entry for each measurement parameter
    for (const measurement of latestMeasurements) {
      normalizedData.push({
        json: {
          id: `${locationId}-${measurement.parameter || 'unknown'}`,
          type: 'air_quality',
          location: {
            coordinates: {
              latitude: latitude,
              longitude: longitude
            }
          },
          locationId: locationId,
          locationName: locationName,
          locality: locality,
          city: locality,
          country: country,
          parameter: measurement.parameter || null,
          value: measurement.value || null,
          unit: measurement.unit || null,
          lastUpdated: measurement.datetime || measurement.lastUpdated || null
        }
      });
    }
  }
}

return normalizedData;
